for (let index = 0; index < keyParts.length; index++) {
  let k = keyParts[index];
  // Ensure we don't allow prototype pollution
  if (INVALID_KEYS.includes(k)) {
    continue;
  }
  if (index >= keyParts.length - 1) {
    current[k] = value;
  }
}
